# Dynamic programming
class Solution(object):
    def maxTurbulenceSize(self, arr):
        """
        :type arr: List[int]
        :rtype: int
        """
        dp1 = [1 for _ in range(len(arr))]
        dp2 = [1 for _ in range(len(arr))]
        for i in range(1, len(arr)):
            if arr[i] > arr[i - 1]:
                dp1[i] = dp2[i - 1] + 1
            elif arr[i] < arr[i - 1]:
                dp2[i] = dp1[i - 1] + 1
        return max(max(dp1), max(dp2))
